#ifndef IR_DASHBOARD_SCRIPT_H
#define IR_DASHBOARD_SCRIPT_H
const char *dashboard_script=R"JS(
let current=1,activeTab='run',files=[],busy=false,examples=[],chosen=null;
const outputs={};let exampleRequest=0,loadingExamples=false;
const byId=id=>document.getElementById(id);
const size=bytes=>Number(bytes).toLocaleString('ru-RU')+' Б ('+(bytes/1048576).toFixed(2)+' МиБ)';
function consoleInfo(){const text=byId('output').textContent,r=byId('output').getBoundingClientRect();byId('consoleInfo').textContent=new TextEncoder().encode(text).length.toLocaleString('ru-RU')+' байт · '+text.split('\n').length+' строк · '+Math.round(r.width)+' × '+Math.round(r.height)+' px'}
function output(text){byId('output').textContent=text;outputs[current]=text;consoleInfo()}
function reportUrl(ext){return '/report?lab='+current+'&format='+ext}
function showTab(tab){activeTab=tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));['run','code','sources','report'].forEach(x=>byId('panel-'+x).classList.toggle('hidden',x!==tab));if(tab==='code')showFiles();if(tab==='report'){byId('pdfLink').href=reportUrl('pdf');byId('docxLink').href=reportUrl('docx');byId('reportFrame').src=reportUrl('pdf')}consoleInfo()}
async function selectLab(id){if(busy)return;current=id;const lab=labs.find(x=>x.id===id);byId('labTitle').textContent=lab.title;byId('labDescription').textContent=lab.description;output(outputs[id]||'Выберите пример и нажмите кнопку с командой.');document.querySelectorAll('.navlab').forEach(x=>x.classList.toggle('active',Number(x.dataset.lab)===id));showTab(activeTab);await loadExamples(null)}
async function loadExamples(preferredId){
    const ticket=++exampleRequest,id=current,input=byId('documentCount'),value=input.value;
    byId('runButton').disabled=true;byId('exampleList').replaceChildren();
    if(!/^[0-9]+$/.test(value)||!Number.isSafeInteger(Number(value))||Number(value)<1||(input.max&&Number(value)>Number(input.max))){loadingExamples=false;byId('runStatus').textContent='Введите целое число от 1 до '+(input.max||'размера корпуса');return}
    loadingExamples=true;byId('runStatus').textContent='Подготовка команды…';
    try{const response=await fetch('/api/examples?lab='+id+'&documents='+encodeURIComponent(value));const rows=await response.json();if(ticket!==exampleRequest||current!==id)return;if(!response.ok)throw Error(rows.output||'Не удалось загрузить примеры');examples=rows;if(rows.length){input.max=rows[0].max_documents;byId('documentHelp').textContent=' От 1 до '+rows[0].max_documents.toLocaleString('ru-RU')+'. Первые статьи по каталогу.'}const selected=rows.find(x=>x.id===preferredId)||rows[0];rows.forEach(item=>{const button=document.createElement('button');button.className='example';button.textContent=item.title;button.onclick=()=>{if(!busy)chooseExample(item,button)};byId('exampleList').append(button);if(item===selected)chooseExample(item,button)})}catch(error){if(ticket===exampleRequest)byId('runStatus').textContent=error.message}finally{if(ticket===exampleRequest)loadingExamples=false}
}
function chooseExample(item,button){chosen=item;document.querySelectorAll('.example').forEach(x=>x.classList.toggle('active',x===button));byId('demoNote').textContent=item.description;byId('documentControls').classList.toggle('hidden',!item.sample);byId('command').textContent=item.command;byId('runButton').textContent='▶ '+item.command;byId('runButton').disabled=false;byId('runStatus').textContent='Готово к запуску'+(item.sample?' · '+item.documents.toLocaleString('ru-RU')+' документов':'')}
byId('documentCount').oninput=()=>{if(!busy)loadExamples(chosen?chosen.id:null)};
async function showCode(file,button){document.querySelectorAll('.file').forEach(x=>x.classList.remove('active'));if(button)button.classList.add('active');byId('source').textContent='Загрузка '+file+'…';try{const response=await fetch('/api/code?file='+encodeURIComponent(file));const text=await response.text();byId('source').textContent=response.ok?text:'Не удалось открыть файл: '+text}catch(error){byId('source').textContent=error.message}}
function showFiles(){const list=byId('fileList');list.replaceChildren();const selected=files.filter(x=>x.lab===current||x.lab===0).sort((a,b)=>(a.lab===0)-(b.lab===0)||a.path.localeCompare(b.path));selected.forEach((file,index)=>{const button=document.createElement('button');button.className='file';button.textContent=file.path+' · '+size(file.bytes);button.onclick=()=>showCode(file.path,button);list.append(button);if(!index)showCode(file.path,button)});if(!selected.length)byId('source').textContent='Нет доступных исходников'}
byId('runButton').onclick=async()=>{if(busy||loadingExamples||!chosen)return;busy=true;byId('documentCount').disabled=true;byId('runButton').disabled=true;const item=chosen;byId('runStatus').textContent='Выполняется…';output('$ '+item.command+'\n\n');try{const response=await fetch('/api/execute?example='+encodeURIComponent(item.id)+'&documents='+item.documents);const result=await response.json();output('$ '+item.command+'\n\n'+result.output);byId('runStatus').textContent=(result.ok?'Готово':'Ошибка')+(result.elapsed_ms!=null?' · '+(result.elapsed_ms/1000).toFixed(3)+' с · пик памяти '+size(result.peak_rss_bytes):'')}catch(error){output(error.message);byId('runStatus').textContent='Ошибка запуска'}finally{busy=false;byId('documentCount').disabled=false;byId('runButton').disabled=false}};
document.querySelectorAll('[data-info]').forEach(button=>{button.disabled=true;button.dataset.label=button.textContent});
fetch('/api/inspection-commands').then(response=>{if(!response.ok)throw Error('Не удалось загрузить команды проверок');return response.json()}).then(commands=>{document.querySelectorAll('[data-info]').forEach(button=>{const command=commands[button.dataset.info];if(!command)throw Error('Нет команды для '+button.dataset.info);const badge=document.createElement('code');badge.textContent=command;badge.style.display='block';badge.style.whiteSpace='pre-wrap';badge.style.overflowWrap='anywhere';badge.style.textAlign='left';badge.style.marginTop='8px';button.append(badge);button.disabled=false;button.onclick=async()=>{if(busy)return;busy=true;byId('command').textContent=command;byId('runStatus').textContent='Выполняется команда…';output('$ '+command+'\n\n');try{const response=await fetch('/api/info?kind='+button.dataset.info);output('$ '+command+'\n\n'+await response.text());byId('runStatus').textContent=response.ok?'Готово':'Ошибка команды'}catch(error){output('$ '+command+'\n\n'+error.message);byId('runStatus').textContent='Ошибка команды'}finally{busy=false}}})}).catch(error=>{byId('runStatus').textContent=error.message});
byId('clearConsole').onclick=()=>output('');byId('copyConsole').onclick=async()=>{try{await navigator.clipboard.writeText(byId('output').textContent);byId('runStatus').textContent='Вывод скопирован'}catch(error){byId('runStatus').textContent='Не удалось скопировать: '+error.message}};
byId('saveConsole').onclick=()=>{const url=URL.createObjectURL(new Blob([byId('output').textContent],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='lab'+current+'-output.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.addEventListener('resize',consoleInfo);
document.querySelectorAll('.navlab').forEach(x=>x.onclick=()=>selectLab(Number(x.dataset.lab)));document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));fetch('/api/files').then(x=>{if(!x.ok)throw Error('Ошибка списка исходников');return x.json()}).then(x=>{files=x;if(activeTab==='code')showFiles()}).catch(error=>{byId('source').textContent=error.message});
let sourceData=null;const count=n=>n.toLocaleString('ru-RU');
function link(text,url){const a=document.createElement('a');a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a}
function showSources(){const root=byId('sourceRows');root.replaceChildren();const filter=byId('sourceFilter').value.trim().toLowerCase();for(const journal of sourceData.journals){if(!journal.name.toLowerCase().includes(filter))continue;const row=document.createElement('tr');for(const value of [journal.name,count(journal.count),journal.share.toFixed(2)+' %',journal.year_min+'–'+journal.year_max]){const td=document.createElement('td');td.textContent=value;row.append(td)}const examples=document.createElement('td'),details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Статьи и ссылки';details.append(summary);for(const sample of journal.samples){const p=document.createElement('p');p.append(link(sample.title,sample.url));p.append(document.createElement('br'));p.append(link('DOI: '+sample.doi,'https://doi.org/'+sample.doi));details.append(p)}examples.append(details);row.append(examples);root.append(row)}}
fetch('/api/sources').then(async response=>{const data=await response.json();if(!response.ok)throw Error(data.error);return data}).then(data=>{sourceData=data;byId('sourceTotals').textContent=count(data.total)+' статей · '+data.journals.length+' журналов · XML: '+count(data.xml)+' · PDF: '+count(data.pdf);byId('sourceManifest').textContent=data.manifest;showSources()}).catch(error=>{byId('sourceTotals').textContent=error.message});byId('sourceFilter').oninput=()=>{if(sourceData)showSources()};selectLab(1);
)JS";
#endif
